import{_ as t,o as e,c as s,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"用 SQL 查询生成数据点","description":"从保存查询、输出配置到生成数据点，区分完整结果集与字段提取，并核对真实读取值。","frontmatter":{"title":"用 SQL 查询生成数据点","description":"从保存查询、输出配置到生成数据点，区分完整结果集与字段提取，并核对真实读取值。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/sql-datapoints.md","filePath":"zh/使用指南/用SQL查询生成数据点.md"}'),i={name:"zh/guide/sql-datapoints.md"};function o(d,a,n,p,l,h){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="用-sql-查询生成数据点" tabindex="-1">用 SQL 查询生成数据点 <a class="header-anchor" href="#用-sql-查询生成数据点" aria-label="Permalink to &quot;用 SQL 查询生成数据点&quot;">​</a></h1><p>本页从已可访问的数据库连接开始。目标是把查询结果保存成工程可引用的数据点，而不是只在屏幕上执行一次 SQL。</p><p>入口：<strong>数据中心 → 接入源 → 对应数据库或内置关系库连接</strong>。先取得业务库的查询授权；涉及真实数据写入的 SQL 不属于本页入门练习。</p><h2 id="_1-打开已有查询-或准备新查询" tabindex="-1">1. 打开已有查询，或准备新查询 <a class="header-anchor" href="#_1-打开已有查询-或准备新查询" aria-label="Permalink to &quot;1. 打开已有查询，或准备新查询&quot;">​</a></h2><p>左侧 **“查询”**区域显示已保存的查询，可通过“筛选表或查询”定位名称；不需要到源码编辑器找 SQL 文件。</p><p>AI 已经保存了查询时，先在连接的保存查询区域按名称查找并双击打开，不重复创建。</p><p>手工练习时使用 <strong>“新建查询”</strong>。例如下面只返回一行演示数值，不代表现场温度：</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 25</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> temperature;</span></span></code></pre></div><p>点击 <strong>“运行”</strong>，核对字段和结果。内置库正在创建时等待准备完成，不把暂未就绪当成 SQL 语法错误。</p><p>带参数的实际业务查询要按页面配置测试值。<strong>测试值不会随查询保存</strong>，应另外确认页面或调用方怎样提供运行参数。</p><h2 id="_2-先决定需要哪种输出" tabindex="-1">2. 先决定需要哪种输出 <a class="header-anchor" href="#_2-先决定需要哪种输出" aria-label="Permalink to &quot;2. 先决定需要哪种输出&quot;">​</a></h2><p>点击 <strong>“输出配置”</strong>，选择适合用途的形式：</p><table tabindex="0"><thead><tr><th>形式</th><th>适用情况</th></tr></thead><tbody><tr><td>完整查询结果</td><td>页面表格等需要整份结果集；值是包含 fields、rows、rowCount 的数据集对象</td></tr><tr><td>提取单个字段</td><td>计算或报警需要某个字段的独立值，例如数值温度</td></tr></tbody></table><p><code>rowCount</code> 不等于数据库全部记录数，需要业务总量时由 SQL 明确返回。不要把完整数据集对象直接拿去和温度阈值比较。</p><p>使用演示温度时，点击 <strong>“提取单个字段”</strong>，在“选择字段”中选择 <code>temperature</code>，检查当前取值和类型。</p><p>字段提取采用第一行的值；多行查询需要用业务条件、排序和范围明确哪一行才有意义。“第一行”不天然表示“最新”。</p><h2 id="_3-保存并生成点" tabindex="-1">3. 保存并生成点 <a class="header-anchor" href="#_3-保存并生成点" aria-label="Permalink to &quot;3. 保存并生成点&quot;">​</a></h2><p>普通 **“保存”**用于保存查询，不等于生成点。确认输出后，点击 <strong>“保存并生成数据点”</strong>；修改已有输出时可能显示 <strong>“保存并更新数据点”</strong>。</p><p>新查询会先要求填写查询名称。保存和生成完成后，核对 **“已生成”**状态与实际数据点完整路径。</p><p>每条 SQL 查询在这里维护一份输出：选择完整结果或单字段提取，不把它当成可以无约束同时生成很多独立字段点的入口。</p><p>未取得字段、没有返回行、提取出错或按钮不可用时，先处理结果和提示，不靠反复点击生成。</p><h2 id="_4-看真实值-而不只看查询结果表" tabindex="-1">4. 看真实值，而不只看查询结果表 <a class="header-anchor" href="#_4-看真实值-而不只看查询结果表" aria-label="Permalink to &quot;4. 看真实值，而不只看查询结果表&quot;">​</a></h2><p>生成后查看 <strong>“数据预览”</strong>，核对值、质量与错误。区分本次 SQL 结果的配置预览与已经生成点后的实际读取，不因样例显示 25 就认定正式数据已读通。</p><p>再进入 <strong>“数据中心” → “数据点”</strong>：</p><ol><li>用完整路径或名称找到点。</li><li>查看详情，核对来源连接、查询、类型和时间。</li><li>使用来源入口返回接入源，确认能找到相同查询。</li><li>AI 参与建模时，可用“配置编写来源 → AI 参与过”辅助查找。</li></ol><h2 id="_5-用到页面、计算和报警" tabindex="-1">5. 用到页面、计算和报警 <a class="header-anchor" href="#_5-用到页面、计算和报警" aria-label="Permalink to &quot;5. 用到页面、计算和报警&quot;">​</a></h2><p>可跟随<a href="/induframe-docs/zh/guide/data-flow-tutorial.html">联动教程</a>，将数值输出接到<a href="/induframe-docs/zh/guide/compute-datapoints.html">计算单元</a>和<a href="/induframe-docs/zh/guide/point-alarms.html">报警配置</a>。</p><p>页面使用时，复制真实路径，并在<a href="/induframe-docs/zh/guide/workspace-datapoints.html">应用开发数据点管理</a>配置合适工程角色的调用权限。</p><p>计算或阈值报警使用时，确认输出是所需的数值、布尔或其他明确类型，而不是结果集对象、空值或字符串形式的数字。</p><p>数据点定义存在不代表持续采样、历史保存或正式部署已启用；这些要按各自配置和运行结果分别核对。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-data-review.html">核对 AI 创建的数据配置</a> · <a href="/induframe-docs/zh/guide/datapoints.html">查看和整理数据点</a>。</p>',31)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
